"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { rove } from "@/lib/0db/rove"
import { Grid } from "@/components/ui/grid"

/** One axis: its name and a number under each series key (`value` when there's one series). */
type RadarDatum = { label: string; value?: number; [key: string]: string | number | undefined }
type RadarSeries = { key: string; label: string }

type RadarChartProps = Omit<React.ComponentProps<"figure">, "children"> & {
  /** One axis per entry, clockwise from the top. Three or more. */
  data: RadarDatum[]
  /** Two or three shapes on one sheet, each read from its key in every datum. */
  series?: RadarSeries[]
  /** Names the chart for assistive tech, e.g. "How the three typefaces compare". */
  label: string
  /** The value at the rim, shared by every axis; the measured figure reads against it (8/10). Defaults to the next round number above the largest. */
  max?: number
  format?: (value: number) => string
  /** The axis the keyboard starts on, and the one a forced hover measures. Defaults to the first. */
  now?: number
  /** The side of one square of the dotted sheet behind, in pixels. */
  cell?: number
  /** Pins the pointed-at look on `now`; set on the root for documentation. */
  "data-force"?: string
}

const figures = new Intl.NumberFormat("en-GB")
// The rim's radius: a third of the plot's width, less where the plot is narrow, so the axis names keep ROOM
// pixels beside it and stay off the sheet's lettered border.
const RIM = 0.34
const ROOM = 76
// How far each dimension line stands off its spoke, in pixels, and how long its end ticks are.
const OFF = 12
const TICK = 5

// ponytail: chart's 1, 2, 2.5, 5, 10 ceiling, kept here so a radar doesn't pull in the bar chart.
function ceiling(n: number) {
  if (n <= 0) return 1
  const p = 10 ** Math.floor(Math.log10(n))
  return ([1, 2, 2.5, 5, 10].find((s) => s * p >= n) ?? 10) * p
}

type XY = [number, number]
const at = (r: number, a: number): XY => [Math.sin(a) * r, -Math.cos(a) * r]
const poly = (p: XY[]) => `M${p.map(([x, y]) => `${x},${y}`).join("L")}Z`

/**
 * Several measures on one shape: a hairline polygon on a dotted construction sheet, each axis named in small caps at
 * its end. Point at an axis, or focus its name, and its value is measured off as a draughtsman's dimension line, from
 * the centre out along the spoke to the point, with its figure set on it.
 */
function RadarChart({ data, series, label, max, format = figures.format, now = 0, cell = 27, className, style, ...props }: RadarChartProps) {
  const force = props["data-force"]?.split(" ").includes("hover")
  const [shown, setShown] = React.useState(force ? now : -1)
  const [w, setW] = React.useState(0)
  const draw = React.useRef<SVGSVGElement>(null)
  const plot = React.useRef<HTMLDivElement>(null)
  React.useEffect(() => {
    const el = draw.current
    if (!el) return
    const ro = new ResizeObserver(([e]) => setW(e.contentRect.width))
    ro.observe(el)
    return () => ro.disconnect()
  }, [])

  const list = series?.length ? series.slice(0, 3) : [{ key: "value", label: "" }]
  const n = data.length
  const read = (d: RadarDatum, k: string) => Math.max(0, Number(d[k] ?? 0) || 0)
  const top = max && max > 0 ? max : ceiling(Math.max(...data.flatMap((d) => list.map((s) => read(d, s.key)))))
  const angle = (i: number) => (i / n) * 2 * Math.PI
  const R = Math.max(0.2 * w, Math.min(RIM * w, w / 2 - ROOM))
  const rest = () => !plot.current?.contains(document.activeElement) && setShown(-1)

  // The axis nearest the pointer, by angle; the very middle keeps what's shown.
  function pick(e: React.PointerEvent) {
    const box = draw.current?.getBoundingClientRect()
    if (!box) return
    const rtl = getComputedStyle(e.currentTarget).direction === "rtl"
    const dx = (e.clientX - box.left - box.width / 2) * (rtl ? -1 : 1)
    const dy = e.clientY - box.top - box.height / 2
    if (Math.hypot(dx, dy) < 8) return
    const t = (Math.atan2(dx, -dy) / (2 * Math.PI) + 1) % 1
    setShown(Math.round(t * n) % n)
  }

  if (n < 3) {
    return (
      <figure data-slot="radar-chart" aria-label={label} className={cn("db-radar", className)} style={style} {...props}>
        <p className="db-radar-note">A radar needs three measures or more; this one has {n}.</p>
      </figure>
    )
  }

  const says = (d: RadarDatum) => list.map((s) => `${s.label ? `${s.label} ` : ""}${format(read(d, s.key))}`).join(", ")

  return (
    <figure
      data-slot="radar-chart"
      data-pointed={shown >= 0 || undefined}
      className={cn("db-radar", className)}
      style={{ "--n": n, "--m": list.length, ...style } as React.CSSProperties}
      {...props}
    >
      <Grid variant="dots" cell={cell} className="db-radar-sheet">
        <div
          ref={plot}
          role="group"
          aria-label={label}
          data-slot="radar-chart-plot"
          className="db-radar-plot"
          style={w ? ({ "--r": `${R}px` } as React.CSSProperties) : undefined}
          onKeyDown={(e) => rove(e, "button", true)}
          onPointerMove={pick}
          onPointerLeave={rest}
          onBlur={(e) => !plot.current?.contains(e.relatedTarget) && setShown(-1)}
        >
          <svg ref={draw} data-slot="radar-chart-draw" className="db-radar-draw" aria-hidden="true">
            {w ? (
              <g transform={`translate(${w / 2} ${w / 2})`}>
                <g className="db-radar-build">
                  {[0.25, 0.5, 0.75, 1].map((q) => (
                    <path key={q} data-rim={q === 1 || undefined} d={poly(data.map((_, i) => at(R * q, angle(i))))} />
                  ))}
                  {data.map((d, i) => {
                    const [x, y] = at(R, angle(i))
                    return <line key={d.label} x1={0} y1={0} x2={x} y2={y} />
                  })}
                </g>
                {list.map((s, k) => {
                  const p = data.map((d, i) => at((R * Math.min(read(d, s.key), top)) / top, angle(i)))
                  return (
                    <g key={s.key} data-series={k} className="db-radar-series">
                      <path className="db-radar-line" d={poly(p)} />
                      {p.map(([x, y], i) => (
                        <circle key={i} className="db-radar-bead" data-shown={i === shown || undefined} cx={x} cy={y} r={3} />
                      ))}
                    </g>
                  )
                })}
                {shown >= 0 ? (
                  // The dimension lines: one per series, stepped off the spoke, from the centre to the point, a tick at each end.
                  <g key={shown} className="db-radar-dims">
                    {list.map((s, k) => {
                      const a = angle(shown)
                      const r = (R * Math.min(read(data[shown], s.key), top)) / top
                      const off = OFF * (k + 1)
                      const [nx, ny] = [Math.cos(a), Math.sin(a)]
                      const [ex, ey] = at(r, a)
                      const [x0, y0, x1, y1] = [nx * off, ny * off, ex + nx * off, ey + ny * off]
                      return (
                        <g key={s.key} data-series={k} className="db-radar-dim">
                          <path d={`M${x0},${y0}L${x1},${y1}M${x0 - nx * TICK},${y0 - ny * TICK}L${x0 + nx * TICK},${y0 + ny * TICK}M${x1 - nx * TICK},${y1 - ny * TICK}L${x1 + nx * TICK},${y1 + ny * TICK}`} />
                        </g>
                      )
                    })}
                  </g>
                ) : null}
              </g>
            ) : null}
          </svg>
          {shown >= 0 && w && list.length === 1
            ? list.map((s, k) => {
                const a = angle(shown)
                const v = read(data[shown], s.key)
                const [mx, my] = at((R * Math.min(v, top)) / top / 2, a)
                // Clear of its dimension line whichever way the spoke runs: half the figure's extent across the spoke.
                const text = `${format(v)}/${format(top)}`
                const off = OFF + 4 + Math.abs(Math.cos(a)) * text.length * 3.8 + Math.abs(Math.sin(a)) * 7
                return (
                  <span
                    key={`${shown}-${s.key}`}
                    data-series={k}
                    className="db-radar-figure"
                    aria-hidden="true"
                    style={{ "--x": `${mx + Math.cos(a) * off}px`, "--y": `${my + Math.sin(a) * off}px` } as React.CSSProperties}
                  >
                    {format(v)}
                    <span className="db-radar-of">/{format(top)}</span>
                  </span>
                )
              })
            : null}
          {data.map((d, i) => {
            const a = angle(i)
            return (
              <button
                key={d.label}
                type="button"
                tabIndex={i === (shown >= 0 ? shown : now) ? 0 : -1}
                data-slot="radar-chart-axis"
                className="db-radar-axis"
                data-shown={i === shown || undefined}
                style={{ "--c": Math.sin(a).toFixed(4), "--s": (-Math.cos(a)).toFixed(4) } as React.CSSProperties}
                aria-label={`${d.label}: ${says(d)} of ${format(top)}`}
                onPointerEnter={() => setShown(i)}
                onFocus={() => setShown(i)}
              >
                {d.label}
              </button>
            )
          })}
        </div>
      </Grid>
      {list.length > 1 ? (
        <figcaption data-slot="radar-chart-key" className="db-radar-key">
          {list.map((s, k) => (
            <span key={s.key} data-series={k} className="db-radar-name">
              <svg className="db-radar-swatch" aria-hidden="true"><line x1="0" y1="50%" x2="100%" y2="50%" /></svg>
              {s.label}
              {shown >= 0 ? <span className="db-radar-key-value"> {format(read(data[shown], s.key))}</span> : null}
            </span>
          ))}
        </figcaption>
      ) : null}
    </figure>
  )
}

export { RadarChart, type RadarChartProps, type RadarDatum, type RadarSeries }

@layer components {
  /* ── db-radar ── several measures on one shape, drawn as Paul Rand draws "design": a dotted construction sheet (the
     grid item), dotted construction polygons at the quarters and dotted spokes, the shape itself one ink hairline with a
     paper bead at each point, and each axis named in small caps at its end. Pointing at an axis measures it off as a
     dimension line, ticked at both ends and stepped off the spoke, with its figure set on it. */
  .db-radar { --dir: 1; margin: 0; display: grid; row-gap: var(--db-space-4); inline-size: min(100%, var(--db-radar-size, 30rem)); }
  .db-radar:is([dir="rtl"], [dir="rtl"] *) { --dir: -1; }
  .db-radar-plot { position: relative; aspect-ratio: 1; cursor: crosshair; }
  .db-radar-draw { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; overflow: visible; pointer-events: none; }
  .db-radar-draw:is([dir="rtl"] *) { scale: -1 1; }

  /* The construction: dotted, faint, the rim a step firmer. */
  .db-radar-build > * { fill: none; stroke: var(--db-rule-strong); stroke-width: var(--db-hairline); stroke-dasharray: 1 4; }
  .db-radar-build > [data-rim] { stroke: var(--db-pencil); stroke-dasharray: 1 3; }

  /* The shape: ink hairline, paper beads. The second series dashed graphite, the third dashed pencil (chart's voices). */
  .db-radar-line { fill: none; stroke: var(--c, var(--db-ink)); stroke-width: var(--db-hairline); stroke-linejoin: round; }
  .db-radar-series[data-series="1"], .db-radar-dim[data-series="1"], .db-radar-name[data-series="1"] { --c: var(--db-graphite); --dash: 4 2; }
  .db-radar-series[data-series="2"], .db-radar-dim[data-series="2"], .db-radar-name[data-series="2"] { --c: var(--db-pencil); --dash: 1 2; }
  .db-radar-series > .db-radar-line { stroke-dasharray: var(--dash, none); }
  .db-radar-bead {
    fill: var(--db-paper); stroke: var(--c, var(--db-ink)); stroke-width: var(--db-hairline);
    transition: r var(--db-moderato) var(--db-spiccato), fill var(--db-allegro) var(--db-exhale);
  }
  .db-radar-series[data-series="0"] > .db-radar-bead[data-shown] { r: 4.5px; fill: var(--db-accent); stroke: var(--db-accent); }

  /* The dimension line: drawn out from the centre along the spoke (moderato, exhale), a tick at each end. */
  .db-radar-dims { animation: db-radar-measure var(--db-moderato) var(--db-exhale) both; transform-origin: 0 0; }
  .db-radar-dim > path { fill: none; stroke: var(--c, var(--db-ink)); stroke-width: var(--db-hairline); }
  @keyframes db-radar-measure { from { scale: 0; opacity: 0; } to { scale: 1; opacity: 1; } }

  .db-radar-figure {
    position: absolute; inset-inline-start: calc(50% + var(--x)); inset-block-start: calc(50% + var(--y)); pointer-events: none;
    font-size: var(--db-pp); line-height: 1; font-variant-numeric: tabular-nums lining-nums; white-space: nowrap;
  }
  .db-radar-figure { translate: -50% -50%; font-weight: 500; color: var(--c, var(--db-ink)); animation: db-radar-set var(--db-moderato) var(--db-exhale) both; }
  .db-radar-figure[data-series="1"] { font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-pp) * var(--db-expression-scale)); font-weight: 400; }
  .db-radar-figure:is([dir="rtl"] *) { translate: 50% -50%; }
  @keyframes db-radar-set { from { opacity: 0; } }
  /* The rim's value after the figure, in pencil: SPECTRA's fractions, the measure against its whole. */
  .db-radar-of { font-weight: 400; color: var(--db-pencil); }

  /* The axis names at the spokes' ends, in small caps, each hung off its end in the direction the spoke runs. The inline
     inset mirrors itself right to left; the translate is physical, so it turns with --dir. */
  .db-radar-axis {
    position: absolute; appearance: none; border: 0; margin: 0; padding: var(--db-space-1); background: none; font: inherit; cursor: crosshair;
    inset-inline-start: calc(50% + var(--c) * (var(--r, 34%) + var(--db-space-2))); inset-block-start: calc(50% + var(--s) * (var(--r, 34%) + var(--db-space-2)));
    translate: calc(var(--dir) * (-50% + var(--c) * 50%)) calc(-50% + var(--s) * 50%);
    inline-size: max-content; max-inline-size: 11em; font-size: var(--db-pp); line-height: var(--db-pp-lh); font-variant-caps: all-small-caps; letter-spacing: 0.08em; font-weight: 500;
    color: var(--db-pencil); text-align: center; transition: color var(--db-allegro) var(--db-exhale);
  }
  .db-radar-axis:is(:hover, :focus-visible, [data-shown]) { color: var(--db-ink); }

  /* With series, a key: each name after a sample of its line, and its figure on the axis you're on. */
  .db-radar-key { display: flex; flex-wrap: wrap; gap: var(--db-space-2) var(--db-space-5); font-size: var(--db-pp); line-height: var(--db-pp-lh); letter-spacing: var(--db-pp-tr); color: var(--db-graphite); }
  .db-radar-name { display: inline-flex; align-items: baseline; gap: var(--db-space-2); }
  .db-radar-name[data-series="1"] { font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-pp) * var(--db-expression-scale)); }
  .db-radar-name[data-series="2"] { color: var(--db-pencil); }
  .db-radar-swatch { inline-size: var(--db-space-5); block-size: 0.5em; overflow: visible; }
  .db-radar-swatch > line { stroke: var(--c, var(--db-ink)); stroke-width: var(--db-hairline); stroke-dasharray: var(--dash, none); }
  .db-radar-key-value { color: var(--db-ink); font-variant-numeric: tabular-nums; }
  .db-radar-note { font-size: var(--db-p); color: var(--db-graphite); }

  @media (forced-colors: active) {
    .db-radar-line, .db-radar-dim > path { stroke: CanvasText; }
    .db-radar-build > * { stroke: GrayText; }
    .db-radar-series[data-series="0"] > .db-radar-bead[data-shown] { fill: Highlight; stroke: Highlight; }
  }
}
